fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    // Create a new vector to hold the result
    let mut new_list = Vec::with_capacity(len);
    
    // Append the subarray from index n to the end
    new_list.extend_from_slice(&list[n..]);
    // Append the subarray from index 0 to n (exclusive)
    new_list.extend_from_slice(&list[0..n]);
    
    new_list
}